package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NegativeCountingTest {
 @Test public void all320SequencesIgnoreKeysAndIdentifyOnlyWrongEntry(){int count=0,cross=0;for(int step=1;step<=10;step++)for(int start=-20;start<=2*step;start++){Question q=NegativeCounting.make(step,start);q.answers=new String[]{"99","99","99"};q.expression="99";List<String> answer=List.of(""+(start-step),""+(start-2*step),""+(start-3*step));assertTrue(new Checker().check(q,List.of(),answer).correct());for(int i=0;i<3;i++){List<String> wrong=new ArrayList<>(answer);wrong.set(i,""+(start-(i+1)*step+1));Checker.Result result=new Checker().check(q,List.of(),wrong);assertEquals(Checker.Status.WRONG_ANSWER,result.status);assertEquals(i,result.index);}HelpPlan p=HelpPlan.forQuestion(q);assertEquals(5,p.size());assertFalse(p.canTransfer());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] entries={start,step,start-step,start-2*step,start-3*step};for(int i=0;i<5;i++)assertTrue(p.step(i).accepts(""+entries[i]));if(start>=0)cross++;count++;}assertEquals(320,count);assertEquals(120,cross);}
 @Test public void actualYearFourExhausts320BeforeOldest(){Generator g=new Generator(new Random(142));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",NegativeCounting.ID,4);List<String> recent=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<320;i++){Question q=g.next(NegativeCounting.ID,recent,false,limits);assertNotNull(NegativeCounting.read(q));assertTrue(seen.add(q.signature()));assertTrue(q.choices.isEmpty());recent.add(q.signature());}assertEquals(recent.get(0),g.next(NegativeCounting.ID,recent,false,limits).signature());}
 @Test public void invalidPublicSequenceCannotBorrowStoredKeys(){for(String prompt:List.of("0씩 거꾸로 세세요.\n0 → □ → □ → □","11씩 거꾸로 세세요.\n0 → □ → □ → □","1씩 거꾸로 세세요.\n3 → □ → □ → □","1씩 거꾸로 세세요.\n-21 → □ → □ → □","1씩 앞으로 세세요.\n0 → □ → □ → □")){Question q=new Question(NegativeCounting.ID,prompt,"0","0","0","0");assertNull(NegativeCounting.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0","0","0")).status);}}
}
